def todoist_create_task(task=None, tasks=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "todoist_create_task"

    _re_prj = re.compile(r"^tdst_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    _re_sec = re.compile(r"^tdst_sec_[0-9A-HJKMNP-TV-Z]{10,}$")
    _re_tsk = re.compile(r"^tdst_tsk_[0-9A-HJKMNP-TV-Z]{10,}$")
    _re_lbl = re.compile(r"^tdst_lbl_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(ok, err_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "error_code": err_code,
            "http_status": 200 if ok else 400,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso_z(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _bump_usage_and_check_quota():
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_iso_z()
        today = now[:10]
        if not usage:
            usage = [{
                "id": "usage_default",
                "window": "day",
                "window_start": today + "T00:00:00Z",
                "requests_today": 0,
                "limit_per_day": 5000
            }]
        u = usage[0] if isinstance(usage[0], dict) else {}
        ws = u.get("window_start")
        if isinstance(ws, str) and len(ws) >= 10 and ws[:10] != today:
            u["window_start"] = today + "T00:00:00Z"
            u["requests_today"] = 0
        limit = u.get("limit_per_day")
        used = int(u.get("requests_today") or 0)
        if isinstance(limit, int) and used >= limit:
            usage[0] = u
            _save("usage.json", usage)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit_per_day=limit, requests_today=used)
        u["requests_today"] = used + 1
        if usage:
            usage[0] = u
        _save("usage.json", usage)
        return None

    # quota check (counts every call)
    qerr = _bump_usage_and_check_quota()
    if qerr:
        _append_log(False, qerr["error"]["code"])
        return qerr

    # Accept either `task`, `tasks`, or allow both (vendor surface sometimes sends both). Prefer `task` if present.
    payloads = None
    if isinstance(task, dict):
        payloads = [task]
    elif isinstance(tasks, list):
        payloads = tasks
    elif task is None and tasks is None:
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either 'task' or 'tasks' must be provided.")
    else:
        # malformed types
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid payload: expected 'task' object or 'tasks' array.")

    if not isinstance(payloads, list) or len(payloads) == 0:
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid payload: no tasks to create.")

    allowed_keys = {
        "project_id", "section_id", "parent_task_id", "content", "description", "priority",
        "due", "deadline", "duration", "order_index", "is_recurring", "label_ids"
    }

    projects = _load("projects.json")
    sections = _load("sections.json")
    tasks_rows = _load("tasks.json")
    labels = _load("labels.json")
    task_labels_rows = _load("task_labels.json")

    if not isinstance(projects, list): projects = []
    if not isinstance(sections, list): sections = []
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(labels, list): labels = []
    if not isinstance(task_labels_rows, list): task_labels_rows = []

    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    sec_by_id = {s.get("id"): s for s in sections if isinstance(s, dict)}
    task_by_id = {t.get("id"): t for t in tasks_rows if isinstance(t, dict)}
    label_by_id = {l.get("id"): l for l in labels if isinstance(l, dict)}

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(26))}"

    # Pre-validate all payloads first (atomic-ish)
    for idx, p in enumerate(payloads):
        if not isinstance(p, dict):
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each task payload must be an object.", index=idx)
        extra_keys = set(p.keys()) - allowed_keys
        if extra_keys:
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unexpected field(s) in task payload.", index=idx, fields=sorted(extra_keys))
        content = p.get("content")
        project_id = p.get("project_id")
        if not isinstance(content, str) or not content.strip():
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Missing/invalid required field 'content'.", index=idx)
        if not isinstance(project_id, str) or not _re_prj.match(project_id):
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Missing/invalid required field 'project_id'.", index=idx)
        prj = proj_by_id.get(project_id)
        if not prj or prj.get("status") != "active":
            _append_log(False, "NOT_FOUND" if not prj else "CONFLICT")
            return _err("CONFLICT" if prj else "NOT_FOUND", "project_id must reference an active project.", index=idx, project_id=project_id)

        section_id = p.get("section_id")
        if section_id is not None:
            if not isinstance(section_id, str) or not _re_sec.match(section_id):
                _append_log(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid 'section_id' format.", index=idx)
            sec = sec_by_id.get(section_id)
            if not sec or sec.get("status") != "active":
                _append_log(False, "NOT_FOUND" if not sec else "CONFLICT")
                return _err("CONFLICT" if sec else "NOT_FOUND", "section_id must reference an active section.", index=idx, section_id=section_id)
            if sec.get("project_id") != project_id:
                _append_log(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "section_id must belong to the same project_id as the task.", index=idx, section_id=section_id, project_id=project_id)

        parent_task_id = p.get("parent_task_id")
        if parent_task_id is not None:
            if not isinstance(parent_task_id, str) or not _re_tsk.match(parent_task_id):
                _append_log(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid 'parent_task_id' format.", index=idx)
            pt = task_by_id.get(parent_task_id)
            if not pt or pt.get("status") == "deleted":
                _append_log(False, "NOT_FOUND" if not pt else "CONFLICT")
                return _err("CONFLICT" if pt else "NOT_FOUND", "parent_task_id must reference an existing non-deleted task.", index=idx, parent_task_id=parent_task_id)
            # typical Todoist rule: subtask project is same as parent task project
            if pt.get("project_id") != project_id:
                _append_log(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_task_id must be in the same project_id as the task.", index=idx, parent_task_id=parent_task_id, project_id=project_id)

        priority = p.get("priority", 1)
        if priority is None:
            priority = 1
        if not isinstance(priority, int) or priority < 1 or priority > 4:
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4.", index=idx)

        order_index = p.get("order_index")
        if order_index is None:
            order_index = 0
        if not isinstance(order_index, int) or order_index < 0:
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0.", index=idx)

        is_rec = p.get("is_recurring", False)
        if is_rec is None:
            is_rec = False
        if not isinstance(is_rec, bool):
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "is_recurring must be a boolean.", index=idx)

        label_ids = p.get("label_ids")
        if label_ids is not None:
            if not isinstance(label_ids, list) or any((not isinstance(x, str) or not _re_lbl.match(x)) for x in label_ids):
                _append_log(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "label_ids must be an array of label ids.", index=idx)
            # reject attaching deleted labels
            for lid in label_ids:
                lbl = label_by_id.get(lid)
                if not lbl:
                    _append_log(False, "NOT_FOUND")
                    return _err("NOT_FOUND", "Label not found.", index=idx, label_id=lid)
                if lbl.get("status") != "active":
                    _append_log(False, "CONFLICT")
                    return _err("CONFLICT", "Cannot attach a deleted label.", index=idx, label_id=lid)

    now = _now_iso_z()
    created = []
    created_task_labels = []
    # Build fast lookup for unique(task_id,label_id)
    existing_assoc = set()
    for r in task_labels_rows:
        if isinstance(r, dict):
            existing_assoc.add((r.get("task_id"), r.get("label_id")))

    for p in payloads:
        new_id = _gen_id("tdst_tsk")
        while any(t.get("id") == new_id for t in tasks_rows if isinstance(t, dict)):
            new_id = _gen_id("tdst_tsk")

        row = {
            "id": new_id,
            "todoist_task_id": _gen_id("todoist_tsk"),  # local upstream placeholder; must be unique but not validated here
            "project_id": p.get("project_id"),
            "section_id": p.get("section_id", None),
            "parent_task_id": p.get("parent_task_id", None),
            "content": p.get("content").strip(),
            "description": p.get("description", None),
            "priority": int(p.get("priority", 1) if p.get("priority", 1) is not None else 1),
            "due": p.get("due", None),
            "deadline": p.get("deadline", None),
            "duration": p.get("duration", None),
            "order_index": int(p.get("order_index", 0) if p.get("order_index", 0) is not None else 0),
            "is_recurring": bool(p.get("is_recurring", False)),
            "completed_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }

        tasks_rows.append(row)
        created.append(row)

        label_ids = p.get("label_ids") or []
        for lid in label_ids:
            key = (new_id, lid)
            if key in existing_assoc:
                continue
            tlb_id = _gen_id("tdst_tlb")
            while any((isinstance(x, dict) and x.get("id") == tlb_id) for x in task_labels_rows):
                tlb_id = _gen_id("tdst_tlb")
            tlb = {
                "id": tlb_id,
                "task_id": new_id,
                "label_id": lid,
                "source": "user",
                "created_at": now,
                "updated_at": now
            }
            task_labels_rows.append(tlb)
            created_task_labels.append(tlb)
            existing_assoc.add(key)

    _save("tasks.json", tasks_rows)
    _save("task_labels.json", task_labels_rows)

    _append_log(True, meta={"created_tasks": len(created), "created_task_labels": len(created_task_labels)})

    return {
        "tasks": created if len(created) > 1 else None,
        "task": created[0] if len(created) == 1 else None,
        "meta": {"created": len(created)}
    }

def todoist_get_tasks(task_id=None, task_ids=None, project_id=None, section_id=None, parent_task_id=None, status=None, label_id=None, include_labels=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "todoist_get_tasks"

    _re_prj = re.compile(r"^tdst_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    _re_sec = re.compile(r"^tdst_sec_[0-9A-HJKMNP-TV-Z]{10,}$")
    _re_tsk = re.compile(r"^tdst_tsk_[0-9A-HJKMNP-TV-Z]{10,}$")
    _re_lbl = re.compile(r"^tdst_lbl_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(ok, err_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "error_code": err_code,
            "http_status": 200 if ok else 400,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso_z(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _bump_usage_and_check_quota():
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_iso_z()
        today = now[:10]
        if not usage:
            usage = [{
                "id": "usage_default",
                "window": "day",
                "window_start": today + "T00:00:00Z",
                "requests_today": 0,
                "limit_per_day": 5000
            }]
        u = usage[0] if isinstance(usage[0], dict) else {}
        ws = u.get("window_start")
        if isinstance(ws, str) and len(ws) >= 10 and ws[:10] != today:
            u["window_start"] = today + "T00:00:00Z"
            u["requests_today"] = 0
        limit = u.get("limit_per_day")
        used = int(u.get("requests_today") or 0)
        if isinstance(limit, int) and used >= limit:
            usage[0] = u
            _save("usage.json", usage)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit_per_day=limit, requests_today=used)
        u["requests_today"] = used + 1
        if usage:
            usage[0] = u
        _save("usage.json", usage)
        return None

    qerr = _bump_usage_and_check_quota()
    if qerr:
        _append_log(False, qerr["error"]["code"])
        return qerr

    # Relaxed validation: accept list containing any strings; only validate those that look like ids.
    if task_id is not None and (not isinstance(task_id, str) or not _re_tsk.match(task_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'task_id' format.")
    if task_ids is not None:
        if not isinstance(task_ids, list):
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "task_ids must be an array.")
        for x in task_ids:
            if not isinstance(x, str):
                _append_log(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "task_ids must contain strings only.")
            # if provided values don't match task-id pattern, treat as "no matches" rather than error
    if project_id is not None and (not isinstance(project_id, str) or not _re_prj.match(project_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'project_id' format.")
    if section_id is not None and (not isinstance(section_id, str) or not _re_sec.match(section_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'section_id' format.")
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not _re_tsk.match(parent_task_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'parent_task_id' format.")
    if label_id is not None and (not isinstance(label_id, str) or not _re_lbl.match(label_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'label_id' format.")

    if status is not None and status not in ("active", "completed", "deleted"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'status' value.")
    if include_labels is not None and not isinstance(include_labels, bool):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_labels must be a boolean.")
    if sort_by is not None and sort_by not in ("created_at", "updated_at", "order_index", "priority", "completed_at"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'sort_by' value.")
    if sort_order is not None and sort_order not in ("asc", "desc"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'sort_order' value.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    tasks_rows = _load("tasks.json")
    task_labels_rows = _load("task_labels.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(task_labels_rows, list): task_labels_rows = []

    # Default exclude deleted unless explicitly requested
    eff_status = status
    if eff_status is None:
        eff_status = "active"

    # Build label membership map if needed
    task_to_labels = {}
    if include_labels or label_id is not None:
        for r in task_labels_rows:
            if not isinstance(r, dict):
                continue
            tid = r.get("task_id")
            lid = r.get("label_id")
            if not tid or not lid:
                continue
            task_to_labels.setdefault(tid, []).append(lid)

    # Apply explicit selection if provided
    explicit_ids = []
    if task_id is not None:
        explicit_ids = [task_id]
    elif task_ids is not None:
        # Only consider those that match task id pattern as actual ids; others will simply not match.
        explicit_ids = [x for x in task_ids if isinstance(x, str) and _re_tsk.match(x)]

    rows = [r for r in tasks_rows if isinstance(r, dict)]

    if explicit_ids:
        want = set(explicit_ids)
        rows = [r for r in rows if r.get("id") in want]
        # envelope: single task vs multiple tasks
        # For explicit get, do not force status filter beyond default deleted exclusion unless status provided
        if status is None:
            rows = [r for r in rows if r.get("status") != "deleted"]
        elif status is not None:
            rows = [r for r in rows if r.get("status") == status]
    else:
        # list filters
        rows = [r for r in rows if r.get("status") == eff_status]
        if project_id is not None:
            rows = [r for r in rows if r.get("project_id") == project_id]
        if section_id is not None:
            rows = [r for r in rows if r.get("section_id") == section_id]
        if parent_task_id is not None:
            rows = [r for r in rows if r.get("parent_task_id") == parent_task_id]
        if label_id is not None:
            rows = [r for r in rows if label_id in (task_to_labels.get(r.get("id")) or [])]

    # Attach labels if requested
    if include_labels:
        for r in rows:
            rid = r.get("id")
            r = r  # no-op
            r["label_ids"] = list(task_to_labels.get(rid, []))

    # Sorting
    sb = sort_by or "created_at"
    so = sort_order or "asc"

    def _key(v):
        # None-safe ordering
        if v is None:
            return ""
        return v

    try:
        rows.sort(key=lambda r: _key(r.get(sb)))
    except Exception:
        # if sort key missing/heterogeneous, fall back to id sort
        rows.sort(key=lambda r: _key(r.get("id")))
    if so == "desc":
        rows.reverse()

    # Pagination with opaque cursor: base64("offset:<n>")
    def _decode_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4)).decode("utf-8")
        except Exception:
            return None
        if raw.startswith("offset:"):
            try:
                return int(raw.split(":", 1)[1])
            except Exception:
                return None
        return None

    def _encode_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    off = 0
    if cursor is not None:
        off2 = _decode_cursor(cursor)
        if off2 is None or off2 < 0:
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        off = off2

    lim = limit if isinstance(limit, int) else 50
    total = len(rows)
    page = rows[off:off + lim]
    next_off = off + lim
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _append_log(True, meta={"returned": len(page), "total": total, "has_more": has_more})

    # If a single id was requested and found, return as `task`, else `tasks`
    if task_id is not None:
        return {"task": page[0] if page else None}
    if explicit_ids and len(explicit_ids) == 1:
        return {"task": page[0] if page else None}
    return {"tasks": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

def todoist_delete_task(task_id=None, task_ids=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "todoist_delete_task"
    _re_tsk = re.compile(r"^tdst_tsk_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list_db(x):
        return x if isinstance(x, list) else []

    def _append_log(ok, err_code=None, meta=None):
        logs = _ensure_list_db(_load("request_logs.json"))
        logs.append(
            {
                "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": "success" if ok else "error",
                "error_code": err_code,
                "http_status": 200 if ok else 400,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso_z(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _bump_usage_and_enforce():
        usage = _ensure_list_db(_load("usage.json"))
        today = _now_iso_z()[:10]
