        if not isinstance(task_ids, list):
            e = _err("VALIDATION_ERROR", "Invalid 'task_ids' format; expected array of task ids.")
            _append_log(False, e["error"]["code"])
            return e
        for tid in task_ids:
            if not isinstance(tid, str) or not _re_tsk.match(tid):
                e = _err("VALIDATION_ERROR", "Invalid 'task_ids' format; all ids must be task ids.", bad_id=tid)
                _append_log(False, e["error"]["code"])
                return e
        targets = list(dict.fromkeys((targets or []) + task_ids))

    if not targets:
        e = _err("VALIDATION_ERROR", "Either 'task_id' or 'task_ids' must be provided.")
        _append_log(False, e["error"]["code"])
        return e

    tasks = _ensure_list_db(_load("tasks.json"))
    task_labels = _ensure_list_db(_load("task_labels.json"))
    by_id = {r.get("id"): r for r in tasks if isinstance(r, dict) and isinstance(r.get("id"), str)}

    missing = [tid for tid in targets if tid not in by_id]
    if missing:
        e = _err("NOT_FOUND", "One or more tasks do not exist.", missing_task_ids=missing)
        _append_log(False, e["error"]["code"])
        return e

    now = _now_iso_z()
    results = []
    changed = 0
    # Soft delete tasks; idempotent
    for tid in targets:
        row = by_id[tid]
        if row.get("status") == "deleted":
            results.append({"task_id": tid, "deleted": True, "changed": False})
            continue
        row["status"] = "deleted"
        row["updated_at"] = now
        changed += 1
        results.append({"task_id": tid, "deleted": True, "changed": True})

    # Cascade: remove task_labels for those tasks
    target_set = set(targets)
    before_len = len(task_labels)
    task_labels = [tl for tl in task_labels if not (isinstance(tl, dict) and tl.get("task_id") in target_set)]
    removed_assoc = before_len - len(task_labels)

    _save("tasks.json", tasks)
    if removed_assoc:
        _save("task_labels.json", task_labels)

    _append_log(True, meta={"targets": len(targets), "deleted_changed": changed, "associations_removed": removed_assoc})
    if len(results) == 1 and task_id is not None and (task_ids is None or task_ids == []):
        return {"result": results[0]}
    return {"results": results, "count": len(results), "deleted_changed": changed, "associations_removed": removed_assoc}

