def todoist_get_projects(project_id=None, project_ids=None, parent_project_id=None, status=None, is_favorite=None, view_style=None, include_hierarchy=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "todoist_get_projects"
    pat = re.compile(r"^tdst_prj_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(ok, err_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "error_code": err_code,
            "http_status": 200 if ok else 400,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso_z(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _bump_usage_and_check_quota():
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_iso_z()
        today = now[:10]
        if not usage:
            usage = [{
                "id": "usage_default",
                "window": "day",
                "window_start": today + "T00:00:00Z",
                "requests_today": 0,
                "limit_per_day": 5000
            }]
        u = usage[0] if isinstance(usage[0], dict) else {}
        ws = u.get("window_start")
        if isinstance(ws, str) and len(ws) >= 10 and ws[:10] != today:
            u["window_start"] = today + "T00:00:00Z"
            u["requests_today"] = 0
        limit = u.get("limit_per_day")
        used = int(u.get("requests_today") or 0)
        if isinstance(limit, int) and used >= limit:
            usage[0] = u
            _save("usage.json", usage)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit_per_day=limit, requests_today=used)
        u["requests_today"] = used + 1
        if usage:
            usage[0] = u
        _save("usage.json", usage)
        return None

    qerr = _bump_usage_and_check_quota()
    if qerr:
        _append_log(False, qerr["error"]["code"])
        return qerr

    if project_id is not None and (not isinstance(project_id, str) or not pat.match(project_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed.")
    if project_ids is not None:
        if not isinstance(project_ids, list) or any((not isinstance(x, str) or not pat.match(x)) for x in project_ids):
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_ids must be an array of well-formed project ids.")
    if parent_project_id is not None and (not isinstance(parent_project_id, str) or not pat.match(parent_project_id)):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_project_id is malformed.")
    if status is not None and status not in ("active", "archived", "deleted"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'status' value.")
    if is_favorite is not None and not isinstance(is_favorite, bool):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean.")
    if view_style is not None and view_style not in ("list", "board", "calendar", "unknown"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'view_style' value.")
    if include_hierarchy is not None and not isinstance(include_hierarchy, bool):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_hierarchy must be a boolean.")
    if sort_by is not None and sort_by not in ("order_index", "name", "created_at", "updated_at"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'sort_by' value.")
    if sort_order is not None and sort_order not in ("asc", "desc"):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'sort_order' value.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        _append_log(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    rows = [p for p in projects if isinstance(p, dict)]

    # Default exclude deleted unless explicitly asked
    if status is None:
        rows = [p for p in rows if p.get("status") != "deleted"]

    explicit_ids = []
    if project_id is not None:
        explicit_ids = [project_id]
    elif project_ids is not None:
        explicit_ids = project_ids

    if explicit_ids:
        want = set(explicit_ids)
        rows = [p for p in rows if p.get("id") in want]
        if status is not None:
            rows = [p for p in rows if p.get("status") == status]
    else:
        if parent_project_id is not None:
            rows = [p for p in rows if p.get("parent_project_id") == parent_project_id]
        if status is not None:
            rows = [p for p in rows if p.get("status") == status]
        if is_favorite is not None:
            rows = [p for p in rows if bool(p.get("is_favorite")) == is_favorite]
        if view_style is not None:
            rows = [p for p in rows if p.get("view_style") == view_style]

    if include_hierarchy:
        by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        children = {}
        for p in projects:
            if not isinstance(p, dict):
                continue
            pid = p.get("parent_project_id")
            if pid:
                children.setdefault(pid, []).append(p.get("id"))
        for p in rows:
            pid = p.get("id")
            p["parent"] = by_id.get(p.get("parent_project_id")) if p.get("parent_project_id") else None
            p["child_project_ids"] = list(children.get(pid, []))

    sb = sort_by or "order_index"
    so = sort_order or "asc"

    def _key(v):
        if v is None:
            return ""
        return v

    try:
        rows.sort(key=lambda r: _key(r.get(sb)))
    except Exception:
        rows.sort(key=lambda r: _key(r.get("id")))
    if so == "desc":
        rows.reverse()

    def _decode_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4)).decode("utf-8")
        except Exception:
            return None
        if raw.startswith("offset:"):
            try:
                return int(raw.split(":", 1)[1])
            except Exception:
                return None
        return None

    def _encode_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    off = 0
    if cursor is not None:
        off2 = _decode_cursor(cursor)
        if off2 is None or off2 < 0:
            _append_log(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        off = off2

    lim = limit if isinstance(limit, int) else 50
    total = len(rows)
    page = rows[off:off + lim]
    next_off = off + lim
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _append_log(True, meta={"returned": len(page), "total": total, "has_more": has_more})

    if project_id is not None:
        return {"project": page[0] if page else None}
    if explicit_ids and len(explicit_ids) == 1:
        return {"project": page[0] if page else None}
    return {"projects": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

