    if projects is not None:
        if not isinstance(projects, list):
            e = _err("VALIDATION_ERROR", "'projects' must be an array.")
            _append_log(False, e["error"]["code"])
            return e
        for p in projects:
            if not isinstance(p, dict):
                e = _err("VALIDATION_ERROR", "Each item in 'projects' must be an object.")
                _append_log(False, e["error"]["code"])
                return e
        payloads.extend(projects)

    if not payloads:
        e = _err("VALIDATION_ERROR", "Provide 'project' or 'projects'.")
        _append_log(False, e["error"]["code"])
        return e

    # Validate fields
    for p in payloads:
        if "name" not in p or not isinstance(p.get("name"), str) or not p.get("name").strip():
            e = _err("VALIDATION_ERROR", "Project 'name' is required.")
            _append_log(False, e["error"]["code"])
            return e
        if "parent_project_id" in p and p["parent_project_id"] is not None:
            if not isinstance(p["parent_project_id"], str) or not _re_prj.match(p["parent_project_id"]):
                e = _err("VALIDATION_ERROR", "Invalid 'parent_project_id' format.")
                _append_log(False, e["error"]["code"])
                return e
        if "is_favorite" in p and p["is_favorite"] is not None and not isinstance(p["is_favorite"], bool):
            e = _err("VALIDATION_ERROR", "'is_favorite' must be boolean.")
            _append_log(False, e["error"]["code"])
            return e
        if "order_index" in p and p["order_index"] is not None:
            if not isinstance(p["order_index"], int) or p["order_index"] < 0:
                e = _err("VALIDATION_ERROR", "'order_index' must be an integer >= 0.")
                _append_log(False, e["error"]["code"])
                return e
        if "view_style" in p and p["view_style"] is not None:
            if not isinstance(p["view_style"], str) or p["view_style"] not in allowed_view:
                e = _err("VALIDATION_ERROR", "Invalid 'view_style'.")
                _append_log(False, e["error"]["code"])
                return e
        for k in p.keys():
            if k not in {"name", "parent_project_id", "color", "is_favorite", "view_style", "order_index"}:
                e = _err("VALIDATION_ERROR", f"Unknown field '{k}' in project payload.")
                _append_log(False, e["error"]["code"])
                return e

    rows = _load("projects.json")
    if not isinstance(rows, list):
        rows = []

    by_id = {r.get("id"): r for r in rows if isinstance(r, dict)}
    by_todoist = {r.get("todoist_project_id"): r for r in rows if isinstance(r, dict) and isinstance(r.get("todoist_project_id"), str)}

    # Parent must exist and be active if provided
    for p in payloads:
        pid = p.get("parent_project_id")
        if pid is not None:
            parent = by_id.get(pid)
            if not parent:
                e = _err("NOT_FOUND", "parent_project_id not found.", parent_project_id=pid)
                _append_log(False, e["error"]["code"])
                return e
            if parent.get("status") != "active":
                e = _err("CONFLICT", "parent_project_id must reference an active project.", parent_project_id=pid, status=parent.get("status"))
                _append_log(False, e["error"]["code"])
                return e

    now = _now_iso_z()
    created = []
    # generate unique todoist_project_id (string) if not provided by schema; since tool doesn't accept it, generate
    for p in payloads:
        new_id = _gen_id("tdst_prj_")
        # todoist_project_id must be unique
        todoist_id = _gen_id("tprj_")
        while todoist_id in by_todoist:
            todoist_id = _gen_id("tprj_")
        order_index = p.get("order_index")
        if order_index is None:
            order_index = 0
        row = {
            "id": new_id,
            "todoist_project_id": todoist_id,
            "parent_project_id": p.get("parent_project_id"),
            "name": p.get("name"),
            "color": p.get("color"),
            "is_favorite": bool(p.get("is_favorite")) if p.get("is_favorite") is not None else False,
            "view_style": p.get("view_style") if p.get("view_style") is not None else "unknown",
            "order_index": order_index,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        rows.append(row)
        by_id[new_id] = row
        by_todoist[todoist_id] = row
        created.append(row)

    _save("projects.json", rows)
    _append_log(True, meta={"created_count": len(created)})

    if project is not None and projects is None and len(created) == 1:
        return {"project": created[0]}
    return {"projects": created, "created_count": len(created)}

def todoist_update_project(project_id=None, project_ids=None, project=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "todoist_update_project"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_call(ok, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"rql_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "error_code": err_code,
            "http_status": 200 if ok else 400,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    if project is None or not isinstance(project, dict):
        _log_call(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project is required and must be an object.")

    prj_pat = re.compile(r"^tdst_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    if project_id is None and project_ids is None:
        _log_call(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either project_id or project_ids must be provided.")
    if project_id is not None and (not isinstance(project_id, str) or not prj_pat.match(project_id)):
        _log_call(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is malformed.")
    if project_ids is not None:
        if not isinstance(project_ids, list) or any((not isinstance(x, str) or not prj_pat.match(x)) for x in project_ids):
            _log_call(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_ids must be an array of well-formed project ids.")

    allowed_view = ("list", "board", "calendar", "unknown")
    allowed_status = ("active", "archived", "deleted")

    if "view_style" in project and project["view_style"] is not None and project["view_style"] not in allowed_view:
        _log_call(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid view_style.")
    if "is_favorite" in project and project["is_favorite"] is not None and not isinstance(project["is_favorite"], bool):
        _log_call(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_favorite must be boolean.")
    if "order_index" in project and project["order_index"] is not None:
        if not isinstance(project["order_index"], int) or project["order_index"] < 0:
            _log_call(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0.")
    if "parent_project_id" in project and project["parent_project_id"] is not None:
        if not isinstance(project["parent_project_id"], str) or not prj_pat.match(project["parent_project_id"]):
            _log_call(False, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_project_id is malformed.")
    if "status" in project and project["status"] is not None and project["status"] not in allowed_status:
        _log_call(False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")

    targets = []
    if project_id is not None:
        targets.append(project_id)
    if project_ids is not None:
        s = set()
        for x in project_ids:
            if x not in s:
                s.add(x); targets.append(x)

    projects_rows = _load("projects.json")
    sections_rows = _load("sections.json")
    tasks_rows = _load("tasks.json")
    task_labels_rows = _load("task_labels.json")

    if not isinstance(projects_rows, list): projects_rows = []
    if not isinstance(sections_rows, list): sections_rows = []
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(task_labels_rows, list): task_labels_rows = []

    proj_by_id = {p.get("id"): p for p in projects_rows if isinstance(p, dict) and "id" in p}
    missing = [pid for pid in targets if pid not in proj_by_id]
    if missing:
        _log_call(False, "NOT_FOUND")
        return _err("NOT_FOUND", "One or more projects were not found.", missing_ids=missing)

    # Parent validation: must exist and be active; prevent self-parent; prevent cycles
    new_parent = project.get("parent_project_id") if "parent_project_id" in project else None
    if "parent_project_id" in project:
        if new_parent is not None:
            parent_row = proj_by_id.get(new_parent)
            if parent_row is None or parent_row.get("status") != "active":
                _log_call(False, "NOT_FOUND")
                return _err("NOT_FOUND", "Parent project not found or not active.", parent_project_id=new_parent)
            # self-parent
            if len(targets) == 1 and new_parent == targets[0]:
                _log_call(False, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Project cannot be its own parent.")
            # cycle check for each target
            def _ancestors(pid):
                anc = set()
                cur = proj_by_id.get(pid, {}).get("parent_project_id")
                while cur is not None and cur in proj_by_id and cur not in anc:
                    anc.add(cur)
                    cur = proj_by_id[cur].get("parent_project_id")
                return anc
            for tid in targets:
                # If setting parent to a descendant of tid => cycle
                if new_parent == tid:
                    _log_call(False, "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Project cannot be its own parent.", project_id=tid)
                desc_anc = _ancestors(new_parent)
                if tid in desc_anc:
                    _log_call(False, "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Reparenting would create a cycle.", project_id=tid, parent_project_id=new_parent)

    now = _now_iso()

    # Status transitions + cascading soft delete
    transitions = {
        "active": ("archived", "deleted"),
        "archived": ("active", "deleted"),
        "deleted": tuple()
    }

    want_status = project.get("status") if "status" in project else None

    # If renaming, no special uniqueness constraint in schema for projects names.
    # Apply updates
    updated_projects = []
    any_effect = False

    # Precompute indexes for cascade operations
    sections_by_project = {}
    for s in sections_rows:
        if isinstance(s, dict):
            sections_by_project.setdefault(s.get("project_id"), []).append(s)
    tasks_by_project = {}
    for t in tasks_rows:
        if isinstance(t, dict):
            tasks_by_project.setdefault(t.get("project_id"), []).append(t)

    for pid in targets:
        row = proj_by_id[pid]
        if row.get("status") == "deleted":
            # allow update? For lifecycle, deleted has no transitions; but other fields should not be mutable realistically.
            # Enforce invalid transition for status changes, and otherwise conflict.
            if want_status is not None:
                if want_status != "deleted":
                    _log_call(False, "INVALID_TRANSITION")
                    return _err("INVALID_TRANSITION", "Cannot transition a deleted project.", project_id=pid, from_status="deleted", to_status=want_status)
                # idempotent (no-op)
            else:
                _log_call(False, "CONFLICT")
                return _err("CONFLICT", "Cannot update a deleted project.", project_id=pid)

        # Apply field updates
        changed = False
        for k in ("name", "color", "is_favorite", "view_style", "order_index", "parent_project_id"):
            if k in project:
                val = project.get(k)
                if k == "name" and val is not None:
                    if not isinstance(val, str) or not val.strip():
                        _log_call(False, "VALIDATION_ERROR")
                        return _err("VALIDATION_ERROR", "name must be a non-empty string.", project_id=pid)
                    val = val.strip()
                if k == "order_index" and val is not None:
                    if not isinstance(val, int) or val < 0:
                        _log_call(False, "VALIDATION_ERROR")
                        return _err("VALIDATION_ERROR", "order_index must be an integer >= 0.", project_id=pid)
                if row.get(k) != val:
                    row[k] = val
                    changed = True

        if want_status is not None:
            cur = row.get("status")
            if want_status != cur:
                if want_status not in transitions.get(cur, ()):
                    _log_call(False, "INVALID_TRANSITION")
                    return _err("INVALID_TRANSITION", "Invalid project status transition.",
                                project_id=pid, from_status=cur, to_status=want_status)
                row["status"] = want_status
                changed = True

                # Cascade soft delete when setting project deleted
                if want_status == "deleted":
                    # soft-delete sections under project
                    for s in sections_by_project.get(pid, []):
                        if not isinstance(s, dict):
                            continue
                        if s.get("status") != "deleted":
                            s["status"] = "deleted"
                            s["updated_at"] = now
                            any_effect = True
                    # soft-delete tasks under project, and delete task_labels (FK cascade behavior)
                    deleted_task_ids = []
                    for t in tasks_by_project.get(pid, []):
                        if not isinstance(t, dict):
                            continue
                        if t.get("status") != "deleted":
                            t["status"] = "deleted"
                            t["updated_at"] = now
                            # completed_at can remain; business rules don't require clearing
                            deleted_task_ids.append(t.get("id"))
                            any_effect = True
                    if deleted_task_ids:
                        before = len(task_labels_rows)
                        task_labels_rows = [tl for tl in task_labels_rows if not (isinstance(tl, dict) and tl.get("task_id") in set(deleted_task_ids))]
                        if len(task_labels_rows) != before:
                            any_effect = True

        if changed:
            row["updated_at"] = now
            any_effect = True
        updated_projects.append(row)

    if not any_effect:
        _log_call(False, "NOT_FOUND")
        return _err("NOT_FOUND", "No projects were updated.")

    _save("projects.json", projects_rows)
    _save("sections.json", sections_rows)
    _save("tasks.json", tasks_rows)
    _save("task_labels.json", task_labels_rows)

    _log_call(True, None)
    return {"projects": updated_projects, "count": len(updated_projects)}

def todoist_get_project_sections(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    endpoint = "todoist_get_project_sections"
    status = "ok"
    error = None

    try:
        sections = _load("sections.json")
        projects = _load("projects.json")
    except (TypeError, ValueError) as e:
        status = "error"
        error = _err("INTERNAL_ERROR", "Failed to read datastore", detail=str(e))
        sections = []
        projects = []

    # No explicit auth parameters; assume ambient auth always allowed per contract.
    # Default behavior: only active sections returned, and only for non-deleted projects.
    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    out = []
    if not error:
        for s in sections:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "active":
                continue
            pid = s.get("project_id")
            p = proj_by_id.get(pid)
            if not p:
                continue
            if p.get("status") == "deleted":
                continue
            out.append(s)

        # stable ordering: by project_id then order_index then created_at then id
        def _key(x):
            oi = x.get("order_index")
            try:
                oi = int(oi)
            except Exception:
                oi = 0
            return (str(x.get("project_id") or ""), oi, str(x.get("created_at") or ""), str(x.get("id") or ""))

        out.sort(key=_key)

    # observable dynamics: request log if present
    try:
        reqlog = _load("request_logs.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential": None,
            "status": status if not error else "error",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", reqlog)
    except Exception:
        # request log is best-effort; do not fail the call
        pass

    if error:
        return error

    return {
        "sections": out,
        "meta": {
            "total": len(out),
            "has_more": False,
            "next_cursor": None,
        }
    }

def todoist_create_project_section(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "todoist_create_project_section"

    # Accept payload from _extra since tool signature has no explicit parameters.
    payload = _extra.get("sections", None)
    if payload is None:
        payload = _extra.get("section", None)
    if payload is None:
        payload = _extra.get("items", None)

    if payload is None:
        # allow single section fields at top-level
        if any(k in _extra for k in ("project_id", "name", "todoist_section_id", "order_index")):
            payload = [_extra]
        else:
            payload = []

    if isinstance(payload, dict):
        payload = [payload]
    if not isinstance(payload, list):
        return _err("VALIDATION_ERROR", "Invalid payload: expected 'sections' as list of objects")

    try:
        sections = _load("sections.json")
        projects = _load("projects.json")
    except (TypeError, ValueError) as e:
        return _err("INTERNAL_ERROR", "Failed to read datastore", detail=str(e))

    if not isinstance(sections, list):
        sections = []
    if not isinstance(projects, list):
        projects = []

    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    existing_by_todoist = {}
    for s in sections:
        if isinstance(s, dict) and s.get("todoist_section_id") is not None:
            existing_by_todoist[str(s.get("todoist_section_id"))] = s

    # Validate all first, including uniqueness (project_id,name) among active
    to_create = []
    seen_todoist_ids = set()
    for i, item in enumerate(payload):
        if not isinstance(item, dict):
            return _err("VALIDATION_ERROR", "Each section must be an object", index=i)

        todoist_section_id = item.get("todoist_section_id")
        project_id = item.get("project_id")
        name = item.get("name")
        order_index = item.get("order_index", 0)

        if todoist_section_id is None or str(todoist_section_id).strip() == "":
            return _err("VALIDATION_ERROR", "todoist_section_id is required", index=i)
        todoist_section_id = str(todoist_section_id)

        if project_id is None or str(project_id).strip() == "":
            return _err("VALIDATION_ERROR", "project_id is required", index=i)
        project_id = str(project_id)

        p = proj_by_id.get(project_id)
        if not p:
            return _err("NOT_FOUND", "Project not found", index=i, project_id=project_id)
        if p.get("status") != "active":
            return _err("INVALID_TRANSITION", "Cannot create section in non-active project", index=i, project_id=project_id, project_status=p.get("status"))

        if name is None or not isinstance(name, str) or name.strip() == "":
            return _err("VALIDATION_ERROR", "name is required", index=i)

        try:
            order_index = int(order_index)
        except Exception:
            return _err("VALIDATION_ERROR", "order_index must be an integer", index=i)
        if order_index < 0:
            return _err("VALIDATION_ERROR", "order_index must be >= 0", index=i)

        if todoist_section_id in seen_todoist_ids:
            return _err("CONFLICT", "Duplicate todoist_section_id within request", index=i, todoist_section_id=todoist_section_id)
        seen_todoist_ids.add(todoist_section_id)

        # unique(todoist_section_id)
        if todoist_section_id in existing_by_todoist:
            # Idempotent-ish: if same upstream id already exists, return existing row if compatible.
            ex = existing_by_todoist[todoist_section_id]
            # If it exists but is for different project or name mismatch, it's a conflict.
            if str(ex.get("project_id")) != project_id:
                return _err("CONFLICT", "todoist_section_id already exists for another project", index=i, todoist_section_id=todoist_section_id)
            if ex.get("status") == "deleted":
                return _err("INVALID_TRANSITION", "Cannot recreate a deleted section with the same todoist_section_id", index=i, todoist_section_id=todoist_section_id)
            # allow returning existing; do not create
            to_create.append(("existing", ex))
            continue

        # unique(project_id, name) where status='active'
        for s in sections:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "active":
                continue
            if str(s.get("project_id")) == project_id and str(s.get("name")) == name:
                return _err("CONFLICT", "Active section with same name already exists in project", index=i, project_id=project_id, name=name)

        to_create.append(("new", {
            "todoist_section_id": todoist_section_id,
            "project_id": project_id,
            "name": name,
            "order_index": order_index
        }))

    created = []
    changed = False
    for kind, obj in to_create:
        if kind == "existing":
            created.append(obj)
            continue
        sid = "sec_" + uuid.uuid4().hex
        row = {
            "id": sid,
            "todoist_section_id": obj["todoist_section_id"],
            "project_id": obj["project_id"],
            "name": obj["name"],
            "order_index": obj["order_index"],
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        sections.append(row)
        created.append(row)
        changed = True

    if changed:
        try:
            _save("sections.json", sections)
        except (OSError, TypeError, ValueError) as e:
            return _err("INTERNAL_ERROR", "Failed to persist sections", detail=str(e))
    else:
        # Must have effect OR be explicitly idempotent; this endpoint isn't declared idempotent.
        # If nothing created because all were existing, treat as CONFLICT? Better to return existing as idempotent behavior.
        # We'll allow idempotent returns if upstream ids existed and were compatible.
        pass

    # request log if present
    try:
        reqlog = _load("request_logs.json")
        if not isinstance(reqlog, list):
            reqlog = []
