        return e

    labels = _ensure_list_db(_load("labels.json"))
    now = _now_iso_z()

    # current active personal names
    active_personal = [r for r in labels if isinstance(r, dict) and r.get("label_type") == "personal" and r.get("status") == "active"]
    active_names = {str(r.get("name")).strip().lower() for r in active_personal if isinstance(r.get("name"), str)}

    def _gen_id(prefix):
        # simple ULID-like stub: base32 Crockford-ish alphabet, not strictly time-ordered
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(16))

    created = []
    # Pre-validate for collisions within request and existing
    new_names = []
    for idx, lp in enumerate(labels_payload):
        if not isinstance(lp, dict):
            e = _err("VALIDATION_ERROR", "Each label must be an object.", index=idx)
            _append_log(False, e["error"]["code"])
            return e
        name = lp.get("name")
        if not isinstance(name, str) or not name.strip():
            e = _err("VALIDATION_ERROR", "Label name must be a non-empty string.", index=idx)
            _append_log(False, e["error"]["code"])
            return e
        nm = name.strip().lower()
        if nm in active_names:
            e = _err("CONFLICT", "Personal label name already exists.", name=name)
            _append_log(False, e["error"]["code"])
            return e
        new_names.append(nm)

    if len(set(new_names)) != len(new_names):
        e = _err("CONFLICT", "Duplicate label names in request.")
        _append_log(False, e["error"]["code"])
        return e

    # Create rows
    # Enforce unique(todoist_label_id) by generating a new unique placeholder todoist id.
    existing_todoist_ids = {r.get("todoist_label_id") for r in labels if isinstance(r, dict)}
    for idx, lp in enumerate(labels_payload):
        new_id = _gen_id("tdst_lbl_")
        while any(isinstance(r, dict) and r.get("id") == new_id for r in labels) or not _re_lbl.match(new_id):
            new_id = _gen_id("tdst_lbl_")

        todoist_id = str(int(time.time() * 1000)) + str(random.randint(1000, 9999))
        while todoist_id in existing_todoist_ids:
            todoist_id = str(int(time.time() * 1000)) + str(random.randint(1000, 9999))
        existing_todoist_ids.add(todoist_id)

        row = {
            "id": new_id,
            "todoist_label_id": todoist_id,
            "name": lp.get("name").strip(),
            "color": lp.get("color"),
            "is_favorite": bool(lp.get("is_favorite")) if lp.get("is_favorite") is not None else False,
            "label_type": "personal",
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        labels.append(row)
        created.append(dict(row))
        active_names.add(row["name"].strip().lower())

    _save("labels.json", labels)
    _append_log(True, meta={"created": len(created)})
    return {"labels": created, "count": len(created)}

