    if not isinstance(label_id, str) or not label_id:
        e = _err("VALIDATION_ERROR", "Missing label identifier ('label_id' or 'id').")
        _append_log(False, e["error"]["code"])
        return e
    if _re_lbl.match(label_id) is None and not label_id.isdigit():
        e = _err("VALIDATION_ERROR", "Invalid label id format.", bad_id=label_id)
        _append_log(False, e["error"]["code"])
        return e

