            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        if not usage:
            usage = [{
                "id": "usage_default",
                "window": "day",
                "window_start": now[:10] + "T00:00:00Z",
                "requests_today": 0,
                "limit_per_day": 5000
            }]
        u = usage[0]
        if isinstance(u, dict):
            ws = u.get("window_start")
            if isinstance(ws, str) and len(ws) >= 10:
                if ws[:10] != now[:10]:
                    u["window_start"] = now[:10] + "T00:00:00Z"
                    u["requests_today"] = 0
            u["requests_today"] = int(u.get("requests_today") or 0) + 1
        _save("usage.json", usage)

