        _append_log(False, e["error"]["code"])
        return e

    labels = _ensure_list_db(_load("labels.json"))
    by_id = {r.get("id"): r for r in labels if isinstance(r, dict) and isinstance(r.get("id"), str)}

    # Validate all operations and detect collisions
    now = _now_iso_z()
    active_shared = [r for r in labels if isinstance(r, dict) and r.get("label_type") == "shared" and r.get("status") == "active"]
    active_names = {r.get("name").strip().lower() for r in active_shared if isinstance(r.get("name"), str)}

    ops = []
    for idx, op in enumerate(renames):
        if not isinstance(op, dict):
            e = _err("VALIDATION_ERROR", "Each rename must be an object.", index=idx)
            _append_log(False, e["error"]["code"])
            return e
        lid = op.get("label_id")
        new_name = op.get("new_name")
        if not isinstance(lid, str) or not _re_lbl.match(lid):
            e = _err("VALIDATION_ERROR", "Invalid 'label_id' format.", bad_id=lid, index=idx)
