            _append_log(False, e["error"]["code"])
            return e
        row = by_id.get(lid)
        if not row or row.get("label_type") != "shared":
            e = _err("NOT_FOUND", "Shared label not found.", label_id=lid)
            _append_log(False, e["error"]["code"])
            return e
        if row.get("status") != "active":
            e = _err("CONFLICT", "Only active shared labels can be renamed.", label_id=lid, status=row.get("status"))
            _append_log(False, e["error"]["code"])
            return e
        ops.append((row, new_name.strip()))

    # Check collisions with existing active shared names, excluding those being renamed (their current names)
    renaming_ids = {r.get("id") for r, _ in ops}
    current_names_excluding = set()
    for r in active_shared:
        if r.get("id") in renaming_ids:
            continue
        if isinstance(r.get("name"), str):
            current_names_excluding.add(r.get("name").strip().lower())

    requested_new_norms = [nm.strip().lower() for _, nm in ops]
    if len(set(requested_new_norms)) != len(requested_new_norms):
        e = _err("CONFLICT", "Rename would create duplicate shared-label names within the request.")
        _append_log(False, e["error"]["code"])
        return e
    for nm in requested_new_norms:
        if nm in current_names_excluding:
            e = _err("CONFLICT", "Rename would collide with an existing shared label name.", name=nm)
            _append_log(False, e["error"]["code"])
            return e

    changed = 0
    updated = []
    for row, new_name in ops:
        if row.get("name") != new_name:
            row["name"] = new_name
            row["updated_at"] = now
            changed += 1
        updated.append(dict(row))

    if changed == 0:
        _append_log(True, meta={"updated": 0})
        return {"labels": updated, "count": len(updated), "changed": 0}

    _save("labels.json", labels)
    _append_log(True, meta={"updated": len(updated), "changed": changed})
    return {"labels": updated, "count": len(updated), "changed": changed}

