    bad = []
    for lid in label_ids:
        lr = label_by_id[lid]
        if lr.get("label_type") != "shared" or lr.get("status") != "active":
            bad.append({"label_id": lid, "label_type": lr.get("label_type"), "status": lr.get("status")})
    if bad:
        e = _err("CONFLICT", "Only active shared labels can be removed via this endpoint.", labels=bad)
        _append_log(False, e["error"]["code"])
        return e

    # Reject attaching/removing labels from deleted tasks? Rule says attempts to attach deleted labels or attach labels to deleted tasks are rejected.
    # For removal, refuse if task is deleted as well (conservative).
    deleted_tasks = [tid for tid in task_ids if task_by_id[tid].get("status") == "deleted"]
    if deleted_tasks:
        e = _err("CONFLICT", "Cannot modify labels for deleted tasks.", task_ids=deleted_tasks)
        _append_log(False, e["error"]["code"])
        return e

    target_tasks = set(task_ids)
    target_labels = set(label_ids)

    before_len = len(task_labels)
    kept = []
    removed_rows = []
    for tl in task_labels:
        if not isinstance(tl, dict):
            kept.append(tl)
            continue
        if tl.get("task_id") in target_tasks and tl.get("label_id") in target_labels:
            removed_rows.append(tl)
            continue
        kept.append(tl)

    removed = before_len - len(kept)
    if removed == 0:
        e = _err("NOT_FOUND", "No matching shared label associations found to remove.")
        _append_log(False, e["error"]["code"], meta={"tasks": len(task_ids), "labels": len(label_ids)})
        return e

    _save("task_labels.json", kept)
    _append_log(True, meta={"associations_removed": removed, "tasks": len(task_ids), "labels": len(label_ids)})
    return {"removed": removed, "removed_associations": removed_rows, "task_ids": task_ids, "label_ids": label_ids}

def todoist_whoami(include_rate_limits=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0417000" if __import__("os").path.isdir("./environment_mix/0417000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _get_request_log_filename():
        candidates = ["requests.json", "request_logs.json", "request_log.json", "audit_logs.json", "audit.json", "usage.json"]
        for c in candidates:
            if os.path.exists(os.path.join(_DB, c)):
                return c
        return "requests.json"

    def _append_log(endpoint, status, credential_id=None, error_code=None, meta=None, started=None):
        fn = _get_request_log_filename()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        ts = _now_iso()
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limits_snapshot(endpoint):
        fn = _get_request_log_filename()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                used += 1
        remaining = max(0, limit - used)
        reset_at = (cutoff + datetime.timedelta(seconds=window_s)).isoformat()
        return {"limit": limit, "used": used, "remaining": remaining, "window_seconds": window_s, "reset_at": reset_at}

    started = time.time()
    endpoint = "todoist_whoami"

    if include_rate_limits is not None and not isinstance(include_rate_limits, bool):
        _append_log(endpoint, "error", error_code="VALIDATION_ERROR", meta={"reason": "include_rate_limits type"}, started=started)
        return _err("VALIDATION_ERROR", "include_rate_limits must be a boolean.")

    # AUTH: since no explicit credential parameter exists, treat presence of any datastore context as authenticated.
    # If store is entirely empty/uninitialized, refuse.
    projects = _load("projects.json")
    tasks = _load("tasks.json")
    labels = _load("labels.json")
    sections = _load("sections.json")

    has_context = False
    for col in (projects, tasks, labels, sections):
        if isinstance(col, list) and len(col) > 0:
            has_context = True
            break

    if not has_context:
        _append_log(endpoint, "error", error_code="UNAUTHORIZED", meta={"reason": "no_datastore_context"}, started=started)
        return _err("UNAUTHORIZED", "Missing or invalid authentication.")

    identity = {
        "type": "ambient",
        "display_name": "Local Todoist MCP Caller",
        "scopes": [
            "projects:read",
            "projects:write",
            "sections:read",
            "sections:write",
            "tasks:read",
            "tasks:write",
            "labels:read",
            "labels:write",
        ],
    }

    resp = {"identity": identity}
    if include_rate_limits:
        resp["rate_limits"] = {
            "todoist_whoami": _rate_limits_snapshot("todoist_whoami"),
            "todoist_update_task_labels": _rate_limits_snapshot("todoist_update_task_labels"),
            "todoist_remove_shared_labels": _rate_limits_snapshot("todoist_remove_shared_labels"),
            "todoist_rename_shared_labels": _rate_limits_snapshot("todoist_rename_shared_labels"),
        }

    _append_log(endpoint, "ok", meta={"include_rate_limits": bool(include_rate_limits)}, started=started)
    return resp
